 current.sections.push(graph);current.document.nodes.graph={kind:"widget",section:"graph"};current.document.nodes.group.children.push("graph");for(const [id,port] of [["parentPort","parent"],["childPort","child"]])current.document.variables[id]={scope:"page",type:"record",mode:"resource",source:{kind:"record",section:"graph",port}};const invalid=s=>explorationViewProblem(current.document,current.sections,s,object.name,name=>infos[name],definitions);assert.equal(invalid(graph),false);
 for(const change of [g=>g.recordVariable="parentPort",g=>g.graphExplorer.outputs.pop(),g=>g.graphExplorer.outputs=undefined,g=>g.graphExplorer.outputs[0].variable="selected",g=>g.graphExplorer.objects[1].labelField="unknown",g=>g.graphExplorer.objects[1].object.app="foreign",g=>g.graphExplorer.relations[0].binding.sourceVersion="missing",g=>g.graphExplorer.outputs[1].object=parent]){const g=structuredClone(graph);change(g);assert.equal(invalid(g),true);}for(const patch of [{owner:"foreign",scope:"overlay"},{source:{kind:"record",section:"graph",port:"missing"}},{mode:"shared"}]){const previous=current.document.variables.childPort;current.document.variables.childPort={...previous,...patch};assert.equal(invalid(graph),true);current.document.variables.childPort=previous;}
 definitions.push({ref:{app:"sample",kind:"query",name:"fixed"},version:"v1",query:{object:object.name,limit:0}});const table=current.sections.find(s=>s.id==="table");table.widget="resource-list";table.resourceList={labelField:"title",statusField:"stage"};delete table.fields;current.document.queries.read.limit=12;current.document.queries.read.sort=["id"];assert.equal(invalid(table),false);current.document.queries.read.limit=100;assert.equal(invalid(table),true);current.document.queries.read.limit=12;table.resourceList.statusTones=[{value:"unknown",tone:"danger"}];assert.equal(invalid(table),true);
